13	    12	// Wait for MongoDB and Redis instead of crashing: they may start after us.
14	    13	async function connectWithRetry() {
15	    14	  for (let attempt = 1; ; attempt++) {
16	    15	    try {
17	    16	      await (await getDb()).command({ ping: 1 });
18	    17	      await getRedis().ping();
19	    18	      await ensureIndexes();
20	    19	      return;
21	    20	    } catch (err) {
22	    21	      console.error(`storage not ready (attempt ${attempt}):`, (err as Error).message);
23	    22	      await sleep(Math.min(2000, 200 * attempt));
24	    23	    }
25	    24	  }
26	    25	}
27	    26	
28	    27	// Last line of defence: log instead of dying on a stray error. Even if the process did die,
29	    28	// nothing would be lost (all work is in MongoDB with leases), but staying up is better.
30	    29	process.on('unhandledRejection', (err) => console.error('unhandled rejection:', (err as Error)?.message ?? err));
31	    30	process.on('uncaughtException', (err) => console.error('uncaught exception:', err.message));
32	    31	
33	    32	async function main() {
34	    33	  const server = createServer(createApp());
35	    34	  attachWebSocket(server);
36	    35	  // listen first so /healthz can say "not ready yet" (503) instead of refusing connections.
37	    36	  // If the port cannot be used (e.g. already taken), exit: a process that cannot serve is useless.
38	    37	  server.on('error', (err) => {
39	    38	    console.error('server error:', err.message);
40	    39	    process.exit(1);
41	    40	  });
42	    41	  server.listen(config.port, () => console.log(`server on http://localhost:${config.port}`));
43	    42	
44	    43	  await connectWithRetry();
45	    44	  state.ready = true;
46	    45	  startOutboxWorker(); // also picks up replies left unsent by an instance that died
47	    46	  console.log('ready');
48	    47	
49	    48	  // graceful stop on SIGTERM / Ctrl+C. A kill -9 skips this, which is why all state is in MongoDB/Redis.
50	    49	  const stop = () => {
51	    50	    state.ready = false; // load balancer stops sending us traffic
52	    51	    stopOutboxWorker(); // stop claiming new send jobs
53	    52	    server.close(() => process.exit(0));
54	    53	    setTimeout(() => process.exit(0), 3000).unref();
55	    54	  };
56	    55	  process.on('SIGTERM', stop);
57	    56	  process.on('SIGINT', stop);
58	    57	}
