     1	import { useEffect, useRef, useState } from 'react';
     2	
     3	export type LiveFrame = { seq: number; type: string; contact: string; [k: string]: unknown };
     4	
     5	// Keeps a WebSocket open for one workspace and calls onFrame for each change.
     6	// If the connection drops it reconnects with ?after=<last seq seen>, so nothing is missed.
     7	export function useLiveEvents(workspace: string | null, onFrame: (f: LiveFrame) => void) {
     8	  const [connected, setConnected] = useState(false);
     9	  const handler = useRef(onFrame);
    10	  handler.current = onFrame;
    11	
    12	  useEffect(() => {
    13	    if (!workspace) return;
    14	    let lastSeq: number | null = null;
    15	    let socket: WebSocket | null = null;
    16	    let retryMs = 500;
    17	    let stopped = false;
    18	    let timer: ReturnType<typeof setTimeout>;
    19	
    20	    const connect = () => {
    21	      const after = lastSeq === null ? '' : '&after=' + lastSeq;
    22	      const proto = location.protocol === 'https:' ? 'wss' : 'ws';
    23	      socket = new WebSocket(`${proto}://${location.host}/ws?workspace=${encodeURIComponent(workspace)}${after}`);
    24	      socket.onopen = () => { setConnected(true); retryMs = 500; };
    25	      socket.onmessage = (m) => {
    26	        const frame = JSON.parse(m.data) as LiveFrame & { current?: number };
    27	        // the server's data was reset: continue from its current seq and reload what is on screen
    28	        if (frame.type === 'reset') {
    29	          lastSeq = frame.current ?? 0;
    30	          handler.current({ seq: lastSeq, type: 'reset', contact: '' });
    31	          return;
    32	        }
    33	        if (typeof frame.seq !== 'number' || (lastSeq !== null && frame.seq <= lastSeq)) return;
    34	        lastSeq = frame.seq;
    35	        handler.current(frame);
    36	      };
    37	      socket.onclose = (e) => {
    38	        setConnected(false);
    39	        if (e.code === 4001) { location.reload(); return; } // signed out elsewhere
    40	        if (stopped) return;
    41	        timer = setTimeout(connect, retryMs);
    42	        retryMs = Math.min(retryMs * 2, 8000); // back off while the server is away
    43	      };
    44	    };
    45	    connect();
    46	    return () => { stopped = true; clearTimeout(timer); socket?.close(); };
    47	  }, [workspace]);
    48	
    49	  return connected;
    50	}
